// Sample-and-hold random voltage, clocked by an external gate
static uint32_t state = 0x1234ABCD;

static inline uint32_t xorshift(void) {
  state ^= state << 13;
  state ^= state >> 17;
  state ^= state << 5;
  return state;
}

void on_gate_rising(void) {
  uint16_t v = xorshift() & 0x0FFF; // 12-bit DAC
  dac_write(v);
}
